import React, { PropsWithChildren } from "react";
import clsx from "clsx";
import { Badge as BadgeStyles } from "@airbus/styles";
import { createUseStyles } from "../../lib/styling";
import { CommonProps } from "../helperTypes";

const useStyles = createUseStyles(BadgeStyles, "badge");

// FIXME default ariaLabel value ? or getAriaLabel function prop with count parameter ?
type Variants = "default" | "info" | "success" | "warning" | "error";

type Props = PropsWithChildren<{
  /** Specify the label for screen readers */
  "aria-label"?: string;
  /**
   * The count to show
   * @default ""
   */
  count?: number | string;
  /**
   * Max count to show (with +)
   * @default 99
   */
  max?: number;
  /** Optional horizontal and vertical offset to apply depending on placement */
  offset?: (number|string)[];
  /**
   * Placement
   * @default topright for count / bottomright for status
   */
  placement?: "topleft" | "topright" | "bottomleft" | "bottomright";
  /**Type of the badge component
   * @default notification
   */
  type?: "notification" | "status";
  /**
   * The variant of the badge.
   * @default default
   */
  variant?: Variants;
}>;

export type BadgeProps = Props & CommonProps;

const Badge = (props: BadgeProps) => {
  const {
    "aria-label": ariaLabel,
    children,
    className,
    count = "",
    max = 99,
    placement,
    offset,
    style,
    type = "notification",
    variant,
    ...rest
  } = props;
  const classes = useStyles();
  const offsetStyles = React.useMemo(() => {
    if (!offset) return undefined;
    if (placement === "topright") {
      return { right: offset[0], top: offset[1] };
    } else if (placement === "bottomright") {
      return { right: offset[0], bottom: offset[1] };
    } else if (placement === "bottomleft") {
      return { left: offset[0], bottom: offset[1] };
    } else if (placement === "topleft") {
      return { left: offset[0], top: offset[1] };
    }
  }, [placement, offset]);

  return (
    <div
      className={clsx(classes.root, className, {
        [classes._error]: variant === "error",
        [classes._success]: variant === "success",
        [classes._warning]: variant === "warning",
        [classes._info]: variant === "info",
        [classes._topleft]: placement === "topleft",
        [classes._topright]: placement === "topright",
        [classes._bottomleft]: placement === "bottomleft",
        [classes._bottomright]: placement === "bottomright",
      })}
      style={style}
    >
      {children}
      <div
        aria-label={ariaLabel}
        className={type === "status" ? classes.status : classes.count}
        role="status"
        style={offsetStyles}
        {...rest}
      >
        {typeof count === "number" && type === "notification"
          ? count > max
            ? `${max}+`
            : count
          : null}
      </div>
    </div>
  );
};

export default Badge;
